import {safeUrl} from './core.mjs';
import {sourceCadence,sourceHighlights,sortSources} from './research.mjs';
import {normalizeAmounts,holdingsModel,eventSelection} from './v08-model.mjs';
import {currentCatalog} from './v08-catalog.mjs';
import {structureAnalysis,riskAnalysis,EMPTY_ANALYTICS} from './diagnostics.mjs';
import {createGraph} from './v08-graph.mjs';
import {createLibrary} from './v08-library.mjs';
import {requestAI} from './v08-ai.mjs';
import {fundTheme,industryExposure} from './v09-industry.mjs';
import {loadPublicData} from './v09-public-data.mjs';
const $=s=>document.querySelector(s),h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pct=v=>Number.isFinite(v)?v.toFixed(2)+'%':'—',cash=v=>Number.isFinite(v)?'¥'+v.toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2}):'—';
const today=()=>new Date().toLocaleDateString('sv-SE',{timeZone:'Asia/Shanghai'});
const read=(k,d)=>{try{return JSON.parse(localStorage.getItem(k))??d;}catch{return d;}};
const put=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v));return true;}catch{toast('保存失败，请导出备份');return false;}};
const btn=(act,label,id='',cls='v7-btn')=>`<button type="button" class="${cls}" data-act="${act}" data-id="${h(id)}">${label}</button>`;
const ext=(url,label)=>safeUrl(url)?`<a class="v7-link" href="${h(safeUrl(url))}" target="_blank" rel="noopener noreferrer">${h(label)}</a>`:'';
const opts=(list,value)=>list.map(([id,name])=>`<option value="${h(id)}" ${id===value?'selected':''}>${h(name)}</option>`).join('');
const NAV=[['holdings','我的持仓','layers'],['analysis','持仓分析','chart'],['news','事件时间轴','file'],['sources','公共资料库','file'],['discussion','观点与核对','file'],['library','我的资料库','bookmark'],['settings','设置','gear']];
const TAB={exposure:'穿透暴露',diversification:'分散有效性',risk:'风险贡献',scenario:'下行承压',boundaries:'个人边界'};
const S={view:'holdings',account:read('zhijian-holdings-v08',{items:[]}),cfg:read('zhijian-v07-cfg',{url:'',key:'',model:''}),focus:'portfolio',detail:'portfolio',analysis:'exposure',timelineMode:'fund',timelineId:'',timelineSearch:'',older:false,sourceId:'',sourceQuery:'',discussionId:'',discussionSearch:'',bounds:read('zhijian-boundaries-v08',{fund:null,company:null,loss:null}),selected:new Set(),ai:null};
const D={funds:[],reference:{funds:[],nodes:[],edges:[],sources:[]},events:[],analytics:EMPTY_ANALYTICS,forum:{records:[],metrics:[]},stocks:[],industry:[],archivedEvents:[],timelineOptions:{fund:[],company:[]},worldStocks:null,market:{boards:[],valuations:[]}};
let L1,graph,library,editingRows=[],addingFund=null,loadingSearch=0;
const model=()=>holdingsModel(S.account,D.funds);
function catalog(){const m=model();return currentCatalog({funds:m.funds,builtAt:D.builtAt},[],D.reference);}
function toast(t){$('#v7-toast').textContent=t;$('#v7-toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#v7-toast').classList.remove('show'),2800);}
function dialog(title,html){$('#v7-dlg-title').textContent=title;$('#v7-dlg-body').innerHTML=html;if(!$('#v7-dialog').open)$('#v7-dialog').showModal();}
function close(){$('#v7-dialog').close();}
async function boot(){
 const [p,e,c,a,f,anchors,reference,industry,market]=await Promise.all([get('data/v07/portfolio.json'),get('data/v07/events.json'),get('data/catalog.json'),get('data/analytics.json',EMPTY_ANALYTICS),get('data/v08/forum.json',{records:[],metrics:[]}),get('data/v08/evidence.json',{sources:[]}),get('data/v08/reference.json',{stocks:[]}),get('data/v09/industry.json',{records:[]}),get('data/v09/market-daily.json',{boards:[],valuations:[]})]);
 D.funds=p.funds;D.builtAt=p.builtAt;D.events=e.events||[];D.reference={...c,sources:[...c.sources,...anchors.sources]};D.analytics=a;D.forum=f;D.stocks=reference.stocks||[];D.industry=industry.records||[];D.market=market;
 try{S.account={...normalizeAmounts(S.account.items||[]),savedAt:S.account.savedAt};}catch{S.account={items:[]};toast('持仓读取失败，原数据已保留');}
 library=createLibrary({dialog,close,toast,render,showNotebook:()=>{location.hash='library';render();},isNotebook:()=>S.view==='library'});
 document.addEventListener('click',onClick);document.addEventListener('submit',onSubmit);document.addEventListener('change',onChange);document.addEventListener('input',onInput);
 window.addEventListener('hashchange',route);window.addEventListener('resize',()=>graph?.fit());route();refreshPublicStreams().catch(()=>{});
}
async function refreshPublicStreams(){const [events,market]=await Promise.all([loadPublicData('v07/events.json',null),loadPublicData('v09/market-daily.json',null)]);if(events){D.events=[...new Map([...D.archivedEvents,...events.events].map(e=>[e.id,e])).values()];D.eventUpdatedAt=events.lastCheckedAt||events.builtAt||null;S.selected=new Set([...S.selected].filter(id=>D.events.some(e=>e.id===id)));}if(market)D.market=market;if(['news','analysis'].includes(S.view)&&!$('#v7-dialog').open&&!/^(INPUT|TEXTAREA|SELECT)$/.test(document.activeElement?.tagName||''))render();}
async function get(path,fallback){try{const r=await fetch('./'+path);if(!r.ok)throw Error(path);return await r.json();}catch(e){if(fallback!==undefined)return fallback;throw e;}}
function route(){const aliases={records:'holdings',timeline:'news',notebook:'library'};let v=location.hash.slice(1)||'holdings';S.view=aliases[v]||v;if(!NAV.some(n=>n[0]===S.view))S.view='holdings';S.selected.clear();render();window.scrollTo({top:0});}
function render(){
 $('#v7-nav').innerHTML=NAV.map(([id,name])=>`<a href="#${id}" class="${S.view===id?'on':''}">${h(name)}</a>`).join('');
 $('#v7-crumb').innerHTML=`<strong>${h(NAV.find(n=>n[0]===S.view)[1])}</strong>`;
 const views={holdings:viewHoldings,analysis:viewAnalysis,news:viewTimeline,sources:viewSources,discussion:viewDiscussion,library:()=>'<h1 class="v7-h1">我的资料库</h1>'+library.notebookView(),settings:viewSettings};
 $('#v7-view').innerHTML=views[S.view]();$('#v7-foot').innerHTML='';$('#v7-pickbar').innerHTML='';graph=null;
 if(S.view==='holdings'&&model().funds.length){graph=createGraph($('#relationship-map'),{details:showDetail,focus:id=>{S.focus=id;showDetail(id);const b=$('#graph-focus-label');if(b)b.textContent=id==='portfolio'?'':model().funds.find(f=>f.id===id)?.name||model().companies.find(c=>c.id===id)?.name||'';}});graph.update(model(),S.focus);paintInspector();}
 library.afterRender();
}
function viewHoldings(){const m=model();return `<div class="v8-pagehead"><h1>我的持仓</h1>${btn('edit-holdings',m.funds.length?'管理持仓':'添加持仓','','v7-btn primary')}</div>
 <section class="v7-card holdings-summary"><div><span>持有总额</span><strong>${cash(m.total)}</strong></div><div><span>基金</span><strong>${m.funds.length}<small>只</small></strong></div><div class="holding-strip">${m.funds.slice(0,5).map(f=>`<button data-act="inspect" data-id="${h(f.id)}"><span>${h(f.name)}</span><strong>${pct(f.share)}</strong></button>`).join('')}${m.funds.length>5?btn('edit-holdings','全部 '+m.funds.length+' 只'):''}</div></section>
 ${m.funds.length?`<section class="v8-map-layout"><div class="v7-card v8-map-card"><div class="v8-sectionhead"><h2>关联图谱</h2><div class="v7-actions">${btn('graph-home','组合')}<span id="graph-focus-label">${h(m.funds.find(f=>f.id===S.focus)?.name||'')}</span>${btn('graph-minus','−')}${btn('graph-plus','＋')}${btn('graph-fit','适应')}</div></div><div id="relationship-map"></div></div><aside class="v7-card v8-inspector" id="v8-inspector" aria-label="对象详情"></aside></section>`:`<div class="v8-start"><span class="v8-start-icon">＋</span><h2>添加基金持仓</h2>${btn('edit-holdings','搜索基金并填写金额','','v7-btn primary')}</div>`}`;}
function showDetail(id){S.detail=id;paintInspector();if(innerWidth<1000)$('#v8-inspector').scrollIntoView({behavior:'smooth',block:'start'});}
function industryPanel(funds,total){const x=industryExposure(funds,D.industry,total);return x.ready?`<h3>行业门类</h3><small class="v8-muted">${h(x.asOf)} · 占${funds.length===1?'基金净资产':'组合'} · 基金金额覆盖 ${pct(x.coverage)}</small><div class="v8-related-list">${x.rows.map(r=>`<div><span>${h(r.name)}</span> <strong>${pct(r.weightPercent)}</strong></div>`).join('')}</div>`:'';}
function themePanel(m){const themes=new Map();for(const f of m.funds){const label=fundTheme(f);if(label)themes.set(label,(themes.get(label)||0)+f.share);}return themes.size?`<h3>基金主题占比</h3><div class="v8-related-list">${[...themes].map(([label,weight])=>`<div><span>${h(label)}</span> <strong>${pct(weight)}</strong></div>`).join('')}</div>`:'';}
function paintInspector(all=false){const m=model(),f=m.funds.find(f=>f.id===S.detail),c=m.companies.find(c=>c.id===S.detail);let html;
 if(f){const old=D.reference.funds.find(x=>x.code===f.code),profile=f.profile;html=`<span class="v8-eyebrow">基金 · ${h(f.code)}</span><h2>${h(f.name)}</h2><div class="v8-detail-value">${cash(f.amount)}<small>${pct(f.share)}</small></div><dl class="v8-properties"><dt>基金类型</dt><dd>${h(f.type)}</dd><dt>管理人</dt><dd>${h(f.manager||'—')}</dd><dt>经理资料</dt><dd>${h(profile?.managerTenures?.map(x=>x.name+' · '+x.startDate).join(' / ')||old?.managerName||'—')}</dd><dt>投资主题</dt><dd>${h(fundTheme(f)||'—')}</dd><dt>跟踪指数</dt><dd>${h(f.indexName||'—')}</dd><dt>托管人</dt><dd>${h(profile?.custodian||'—')}</dd><dt>合同生效日</dt><dd>${h(profile?.contractEffectiveDate||'—')}</dd><dt>管理费／托管费（年）</dt><dd>${pct(profile?.fees?.management?.annualDecimal===null?null:profile?.fees?.management?.annualDecimal*100)} ／ ${pct(profile?.fees?.custody?.annualDecimal===null?null:profile?.fees?.custody?.annualDecimal*100)}</dd><dt>持仓报告日</dt><dd>${h(f.disclosure?.asOf||'—')} · ${f.disclosure?.complete?'全部股票':'部分披露'}</dd></dl><div class="v7-actions">${ext('https://fund.eastmoney.com/'+f.code+'.html','基金档案')}${ext('https://fundf10.eastmoney.com/jjjz_'+f.code+'.html','净值')}${ext('https://guba.eastmoney.com/list,of'+f.code+'.html','基金吧')}</div><h3>关联股票 <small>${f.holdings.length}</small></h3>${btn('all-related',all?'收起':'查看全部',f.id)}<div class="v8-related-list">${[...f.holdings].sort((a,b)=>b.weight-a.weight).slice(0,all?500:10).map(r=>`<button data-act="inspect" data-id="stock${h(r.code)}"><span>${h(r.name)}</span><small>${pct(r.weight)}</small><span>↗</span></button>`).join('')||'<p class="v8-muted">暂无数据</p>'}</div>${industryPanel([f],f.amount)}`;
 }else if(c){const stock=D.stocks.find(x=>x.code===c.code);html=`<span class="v8-eyebrow">股票 · ${h(c.code)}</span><h2>${h(c.name)}</h2><div class="v8-detail-value">${pct(c.share)}<small>占组合</small></div><dl class="v8-properties"><dt>公司全称</dt><dd>${h(stock?.fullName||'—')}</dd><dt>交易所</dt><dd>${h(({SSE:'上交所',SZSE:'深交所',BSE:'北交所'})[stock?.exchange]||'—')}</dd><dt>行业</dt><dd>${h(stock?.industry||'—')}</dd><dt>上市日期</dt><dd>${h(stock?.listingDate||stock?.listingMonth||'—')}</dd></dl><h3>持有路径</h3><div class="v8-related-list">${c.paths.map(p=>`<button data-act="inspect" data-id="${h(p.fundId)}"><span>${h(p.name)}</span><small>${pct(p.weight)}</small><span>↗</span></button>`).join('')}</div><div class="v7-actions">${ext('https://guba.eastmoney.com/list,'+c.code+'.html','股吧')}${btn('go-timeline','事件时间轴',c.id,'v7-link')}${btn('go-source','相关依据',c.id,'v7-link')}</div><small class="v8-muted">${h([...new Set(c.paths.map(p=>p.asOf).filter(Boolean))].join(' / '))}</small>`;
 }else html=`<span class="v8-eyebrow">组合</span><h2>持仓概览</h2><div class="v8-detail-value">${cash(m.total)}</div><dl class="v8-properties"><dt>基金</dt><dd>${m.funds.length} 只</dd><dt>持仓日期</dt><dd>${h(S.account.savedAt?new Date(S.account.savedAt).toLocaleDateString('sv-SE',{timeZone:'Asia/Shanghai'}):today())}</dd></dl>${themePanel(m)}${industryPanel(m.funds,m.total)}<div class="v8-related-list">${m.funds.map(f=>`<button data-act="inspect" data-id="${h(f.id)}"><span>${h(f.name)}</span><small>${pct(f.share)}</small><span>↗</span></button>`).join('')}</div>`;
 $('#v8-inspector').innerHTML=html;if(all)$('#v8-inspector').dataset.all='1';else delete $('#v8-inspector').dataset.all;}
function editHoldings(){editingRows=structuredClone(S.account.items||[]);showHoldingEditor();}
function showHoldingEditor(){dialog('管理持仓',`<form id="holding-form"><div class="v8-fund-search"><input id="holding-search" aria-label="搜索要添加的基金" type="search" placeholder="基金代码或名称" autocomplete="off"><div id="holding-results"></div></div><div class="v8-holding-edit"><div class="v8-edit-header"><span>基金</span><span>当前持有金额（元）</span><span></span></div>${editingRows.map((r,i)=>`<div class="v8-edit-row"><div><strong>${h(r.name)}</strong><small>${h(r.code)}</small></div><input type="number" min="0.01" step="0.01" aria-label="${h(r.name)}持有金额" data-amount-index="${i}" value="${h(r.amount??'')}" required>${btn('remove-holding','×',String(i),'v7-x')}</div>`).join('')}</div><div class="v8-editor-footer"><span>合计 <strong id="editor-total">${cash(editingRows.reduce((s,r)=>s+(Number(r.amount)||0),0))}</strong></span><button class="v7-btn primary" type="submit">保存持仓</button></div></form>`);}
async function ensureL1(){return L1||(L1=await get('data/v07/funds-l1.json'));}
async function search(q,target){const token=++loadingSearch;if(!q.trim()){target.innerHTML='';return;}const list=await ensureL1();if(token!==loadingSearch||!target.isConnected)return;const hits=list.filter(r=>r[0].includes(q)||r[1].toLowerCase().includes(q.toLowerCase())).slice(0,12);target.innerHTML=hits.map(r=>btn('add-fund',`${h(r[1])}<small>${h(r[0])} · ${h(r[2])}</small>`,r[0],'v8-search-result')).join('')||'<span class="v8-muted">未找到基金</span>';}
function stats(cat,m){const weights=Object.fromEntries(m.funds.map(f=>[f.id,f.share]));return {structure:structureAnalysis(cat,weights,{mode:'amount',values:Object.fromEntries(m.funds.map(f=>[f.id,f.amount]))},D.analytics),risk:riskAnalysis(cat,weights,D.analytics)};}
const metric=(name,value)=>`<div class="v8-metric"><span>${name}</span><strong>${value??'—'}</strong></div>`;
const formula=text=>`<details class="v8-formula"><summary>公式</summary><p>${h(text)}</p></details>`;
function marketPanel(){const values=[...new Map([...(D.market.valuations||[])].sort((a,b)=>a.asOf.localeCompare(b.asOf)).map(x=>[x.indexCode,x])).values()];const boards=(D.market.boards||[]).filter(x=>['CPO概念','机器人概念','人形机器人','有色金属'].includes(x.name));return values.length||boards.length?`<details class="v7-card"><summary>市场观察</summary>${values.length?`<h3>指数估值</h3><small class="v8-muted">市盈率（总股本，倍）</small><div class="v8-related-list">${values.map(x=>`<div><span>${h(x.indexName)} · ${h(x.asOf)}</span><strong>${Number.isFinite(x.peTotalShares)?x.peTotalShares.toFixed(2):'—'}</strong></div>`).join('')}</div>`:''}${boards.length?`<h3>概念板块主力成交净额</h3><small class="v8-muted">东方财富口径 · 亿元 · 板块可重叠</small><div class="v8-related-list">${boards.map(x=>`<div><span>${h(x.name)} · ${h(x.asOf)}</span><strong>${Number.isFinite(x.mainNetFlowCNY)?(x.mainNetFlowCNY/1e8).toFixed(2):'—'}</strong></div>`).join('')}</div>`:''}</details>`:'';}
function viewAnalysis(){const m=model();if(!m.funds.length)return `<h1 class="v7-h1">持仓分析</h1><div class="v8-start">${btn('edit-holdings','添加持仓','','v7-btn primary')}</div>`;const cat=catalog(),{structure:s,risk:r}=stats(cat,m);let body='';
 if(S.analysis==='exposure')body=`<small class="v8-muted">${h(s.reportDates.join(' / '))}</small><div class="v8-metrics">${metric('已披露企业占组合',pct(m.covered))}${s.top5!==null?metric('前五大企业占组合',pct(s.top5*100)):''}${s.hhi!==null?metric('股票部分 HHI',s.hhi.toFixed(4)):''}</div><div class="v8-bars">${m.companies.slice(0,10).map(c=>`<div><span>${h(c.name)}</span><progress value="${c.share}" max="${m.companies[0]?.share||100}"></progress><strong>${pct(c.share)}</strong></div>`).join('')}</div>${formula('企业占比 = Σ（基金金额 ÷ 组合总额 × 企业占基金净资产比例）；股票部分 HHI = Σ（企业占股票部分比例²）')}`;
 if(S.analysis==='diversification'){body=`${r.ready?`<div class="v8-metrics">${r.risk.diversificationRatio!==null?metric('分散化比率',r.risk.diversificationRatio.toFixed(3)):''}${r.risk.correlation?.[0]?.[1]!=null?metric('收益相关性',r.risk.correlation[0][1].toFixed(3)):''}</div>`:'<span class="v8-muted">暂无数据</span>'}${formula('相关系数 ρ = cov(r₁,r₂) ÷ (σ₁σ₂)；分散化比率 = Σwᵢσᵢ ÷ σ组合')}`;}
 if(S.analysis==='risk')body=`${r.ready?`<div class="v8-metrics">${metric('组合年化波动',pct(r.risk.annualVol*100))}</div>`:''}${r.ready&&r.risk.riskShares?`<table class="v7-table"><thead><tr><th>基金</th><th>波动贡献</th></tr></thead><tbody>${m.funds.map((f,i)=>`<tr><td>${h(f.name)}</td><td>${pct(r.risk.riskShares?.[i]===null?null:r.risk.riskShares?.[i]*100)}</td></tr>`).join('')}</tbody></table>`:'<span class="v8-muted">暂无数据</span>'}${formula('σ组合 = √(wᵀΣw)；波动贡献份额 = wᵢ(Σw)ᵢ ÷ (wᵀΣw)')}`;
 if(S.analysis==='scenario')body=`${r.path?.ready?`<div class="v8-metrics">${metric('历史最大回撤',pct(r.path.maxDrawdown*100))}</div>`:''}<h3>情景测算</h3><form id="scenario-form" class="v8-inline-form"><label>对象<select name="scope">${opts([['all','整个组合'],...m.funds.map(f=>[f.id,f.name]),...m.companies.slice(0,10).map(c=>[c.id,c.name])],'all')}</select></label><label>假设涨跌（%）<input name="shock" type="number" min="-100" max="100" value="-20" required></label><button class="v7-btn primary">计算</button></form><div id="scenario-result"></div>${formula('情景金额变化 = 组合总额 × 对象占比 × 假设涨跌幅')}`;
 if(S.analysis==='boundaries')body=`<form id="bounds-form" class="v8-inline-form"><label>单只基金上限（%）<input name="fund" type="number" min="0" max="100" value="${S.bounds.fund??''}"></label><label>单一企业上限（%）<input name="company" type="number" min="0" max="100" value="${S.bounds.company??''}"></label><label>损失关注金额（元）<input name="loss" type="number" min="0.01" step="0.01" value="${S.bounds.loss??''}"></label><button class="v7-btn primary">保存</button></form><div class="v8-metrics">${metric('最大基金占比',pct(Math.max(...m.funds.map(f=>f.share))))}${metric('最大已披露企业占比',pct(m.companies[0]?.share))}</div>${S.bounds.fund!==null?`<table class="v7-table"><thead><tr><th>基金</th><th>当前占比</th><th>上限 ${pct(S.bounds.fund)}</th></tr></thead><tbody>${m.funds.map(f=>`<tr><td>${h(f.name)}</td><td>${pct(f.share)}</td><td>${f.share>S.bounds.fund?'超过上限':'范围内'}</td></tr>`).join('')}</tbody></table>`:''}${S.bounds.company!==null?`<table class="v7-table"><thead><tr><th>已披露企业</th><th>占组合</th><th>上限 ${pct(S.bounds.company)}</th></tr></thead><tbody>${m.companies.slice(0,10).map(c=>`<tr><td>${h(c.name)}</td><td>${pct(c.share)}</td><td>${c.share>S.bounds.company?'超过上限':s.complete?'范围内':'—'}</td></tr>`).join('')}</tbody></table>`:''}`;
 return `<h1 class="v7-h1">持仓分析</h1><div class="v8-tabs">${Object.entries(TAB).map(([id,name])=>btn('analysis-tab',name,id,S.analysis===id?'on':'')).join('')}</div><section class="v7-card">${body}</section>${S.analysis==='exposure'?marketPanel():''}`;}
function objectList(mode){const m=model(),held=mode==='fund'?m.funds:m.companies;return S.view==='news'?[...new Map([...held,...D.timelineOptions[mode]].map(x=>[x.id,x])).values()]:held;}
function timelineModel(){const m=model(),selected=objectList('fund').find(x=>x.id===S.timelineId);return selected&&!m.funds.some(x=>x.id===selected.id)?{...m,funds:[...m.funds,{...selected,holdings:selected.holdings||[]}]}:m;}
async function searchTimeline(input){const q=input.value,mode=S.timelineMode;let all;if(mode==='fund'){all=(await ensureL1()).map(([code,name])=>({id:'fund'+code,code,name}));}else{if(!D.worldStocks)D.worldStocks=(await get('data/v09/security-identities.json',{stocks:[]})).stocks;all=D.worldStocks.map(x=>({...x,id:'stock'+x.code}));}if(!input.isConnected||input.value!==q||S.timelineMode!==mode)return;D.timelineOptions[mode]=q?all.filter(x=>[x.name,x.code].join(' ').toLowerCase().includes(q.toLowerCase())).slice(0,50):[];const options=objectList(mode).filter(x=>x.id===S.timelineId||[x.name,x.code].join(' ').toLowerCase().includes(q.toLowerCase()));document.querySelector('[data-timeline-object]').innerHTML='<option value="">选择对象</option>'+opts(options.map(x=>[x.id,x.name+' · '+x.code]),S.timelineId);}
function selector(mode,id,searchText,prefix){const list=objectList(mode).filter(x=>[x.name,x.code].join(' ').toLowerCase().includes(searchText.toLowerCase()));return `<div class="v8-object-picker"><input aria-label="搜索${prefix==='timeline'?'时间轴':'讨论'}对象" data-${prefix}-search value="${h(searchText)}" placeholder="搜索基金或股票"><select aria-label="选择${prefix==='timeline'?'时间轴':'讨论'}对象" data-${prefix}-object><option value="">选择${mode==='fund'?'基金':'公司'}</option>${opts(list.map(x=>[x.id,x.name+' · '+x.code]),id)}</select></div>`;}
function viewTimeline(){const m=timelineModel(),id=S.timelineId;const events=id?eventSelection(D.events,m,S.timelineMode,id,today(),S.older):[];return `<div class="v8-sectionhead"><h1 class="v7-h1">事件时间轴</h1>${D.eventUpdatedAt?`<small class="v8-muted">资料更新 ${h(String(D.eventUpdatedAt).slice(0,10))}</small>`:''}</div><div class="v8-tabs">${btn('timeline-mode','按基金','fund',S.timelineMode==='fund'?'on':'')}${btn('timeline-mode','按公司','company',S.timelineMode==='company'?'on':'')}</div>${selector(S.timelineMode,id,S.timelineSearch,'timeline')}
 ${id?`<div class="v8-sectionhead"><span class="v8-muted">${S.older?'全部事件':'近30天'}</span>${btn('older',S.older?'近30天':'更早事件','','v7-link')}</div><ol class="v7-timeline">${events.map(e=>`<li><time>${h(e.date)} · ${h(e.source)}${e.topics?.length?' · '+h(e.topics.map(t=>t.label).join(' / ')):''}</time><h4>${h(e.title)}</h4>${e.summary?`<p>${h(e.summary)}</p>`:''}<div class="v7-actions">${ext(e.url,'原文')}${btn('collect-event','收藏',e.id,'v7-link')}<label><input type="checkbox" data-event-pick="${h(e.id)}" ${S.selected.has(e.id)?'checked':''}>选择</label></div></li>`).join('')||'<li class="v8-muted">暂未收录</li>'}</ol>${events.length?`<button class="v7-btn" data-act="ai-summary" ${S.selected.size?'':'disabled'}>摘要所选事件</button>`:''}`:''}`;}
function sourceRows(objectId=S.sourceId){const m=model(),obj=objectId,oldNode=D.reference.nodes.find(n=>n.id===obj||'stock'+n.code===obj);let ids=null;
 if(obj){const fund=m.funds.find(f=>f.id===obj);ids=new Set(fund?[fund.id,...fund.holdings.map(r=>D.reference.nodes.find(n=>n.code===r.code)?.id||'stock'+r.code)]:[oldNode?.id||obj]);}
 return sortSources(D.reference.sources.filter(s=>s.visibility!=='internal'&&sourceCadence(s)!=='news'&&(!ids||s.entities.some(id=>ids.has(id)))&&[s.title,s.publisher,s.summary].join(' ').includes(S.sourceQuery)));
}
function viewSources(){const m=model(),list=sourceRows();return `<h1 class="v7-h1">公共资料库</h1><div class="v8-object-picker"><input aria-label="搜索依据" id="source-query" placeholder="搜索条款、报告或规则" value="${h(S.sourceQuery)}"><select aria-label="资料关联对象" id="source-object"><option value="">全部对象</option>${opts([...m.funds,...m.companies].map(x=>[x.id,x.name]),S.sourceId)}</select></div><div class="v8-evidence-tabs"><span>条款 · 报告 · 规则</span>${btn('source-qa','问答')}</div><section class="v7-card"><table class="v7-table"><thead><tr><th>资料</th><th>日期</th><th>来源</th><th></th></tr></thead><tbody>${list.map(s=>`<tr><td>${btn('source-detail',h(s.title),s.id,'v7-link')}</td><td>${h(s.publishedAt||('查看 '+(s.retrievedAt||'—')))}</td><td>${h(s.publisher)}</td><td>${btn('collect-source','收藏',s.id,'v7-link')}</td></tr>`).join('')}</tbody></table>${list.length?'':'<p class="v8-muted">暂无资料</p>'}</section>`;}
function showSource(id){const s=D.reference.sources.find(s=>s.id===id);if(!s)return;dialog(s.title,`<p class="v8-muted">${h(s.publisher)} · ${h(s.publishedAt||'')} · ${h(s.period||'')}</p>${s.summary?`<p>${h(s.summary.replace(/本网站[^。]*。?/g,''))}</p>`:''}${s.dataPoints?.length?`<table class="v7-table"><thead><tr><th>指标</th><th>数值</th><th>时期</th></tr></thead><tbody>${s.dataPoints.map(p=>`<tr><td>${h(p.label)}</td><td>${h(p.value)}</td><td>${h(p.period)}</td></tr>`).join('')}</tbody></table>`:''}<p class="v8-muted">${h((s.locator||'').replace(/[（(]零基页号[^）)]*[）)]/g,''))}</p><div class="v7-actions">${ext(s.url,'原文')}${btn('collect-source','收藏',s.id)}${btn('source-summary','摘要',s.id)}</div>`);}
function viewDiscussion(){const mode=S.discussionId.startsWith('stock')?'company':'fund';const id=S.discussionId,m=model(),obj=[...m.funds,...m.companies].find(x=>x.id===id),rows=(D.forum.records||[]).filter(x=>x.objectId===id),metricRow=(D.forum.metrics||[]).filter(x=>x.objectId===id).at(-1);return `<h1 class="v7-h1">观点与核对</h1><div class="v8-tabs">${btn('discussion-mode','基金','fund',mode==='fund'?'on':'')}${btn('discussion-mode','公司','company',mode==='company'?'on':'')}</div>${selector(mode,id,S.discussionSearch,'discussion')}${obj?`<div class="v7-actions">${ext('https://guba.eastmoney.com/list,'+(mode==='fund'?'of':'')+obj.code+'.html','打开'+(mode==='fund'?'基金吧':'股吧'))}</div>`:''}
 ${metricRow?`<div class="v8-metrics">${metric('采样帖子',metricRow.sampledPosts)}${metric('关注度 Z 值',Number.isFinite(metricRow.zScore)?metricRow.zScore.toFixed(2):'—')}</div>`:''}${rows.length?rows.map(r=>`<article class="v7-card"><small class="v8-muted">${h(r.date||r.observedAt||'')} · 股吧</small><h3>${h(r.title)}</h3><p>${h(r.claim||'')}</p>${ext(r.url,'原帖')}${btn('forum-verify','核对说法',r.id)}${btn('collect-forum','收藏',r.id,'v7-link')}</article>`).join(''):''}<section class="v7-card"><h2>说法核对</h2><form id="verify-form"><label class="v7-field"><textarea name="claim" rows="3" placeholder="输入需要核对的具体说法" required maxlength="2000"></textarea></label><button class="v7-btn primary">核对</button></form></section>`;}
function viewSettings(){return `<h1 class="v7-h1">设置</h1><section class="v7-card"><h2>模型接口</h2><form id="settings-form"><label class="v7-field"><span>接口地址</span><input name="url" type="url" value="${h(S.cfg.url)}" placeholder="完整 chat/completions 地址"></label><label class="v7-field"><span>API Key</span><input name="key" type="password" autocomplete="off" value="${h(S.cfg.key)}"></label><label class="v7-field"><span>模型名称</span><input name="model" value="${h(S.cfg.model)}"></label><button class="v7-btn primary">保存</button></form></section><section class="v7-card"><h2>持仓备份</h2><div class="v7-actions">${btn('export-account','导出持仓')}${btn('import-account','导入持仓')}<input id="account-file" type="file" accept="application/json" hidden></div></section>`;}
function evidenceMaterials(objectId=S.sourceId){
 const sources=sourceRows(objectId).map(s=>({id:s.id,text:[s.publishedAt,s.period,s.locator,...sourceHighlights(s).map(i=>i.text)].filter(Boolean).join('\n'),url:safeUrl(s.url),date:s.publishedAt||s.retrievedAt||null,locator:(s.locator||'').replace(/[（(]零基页号[^）)]*[）)]/g,'')}));
 const recent=objectId?eventSelection(D.events,model(),objectId.startsWith('fund')?'fund':'company',objectId,today()):[];
 return [...sources,...recent.map(e=>({id:e.id,text:[e.date,e.title,e.summary].filter(Boolean).join(' '),url:safeUrl(e.url),date:e.date,locator:''}))];
}
async function runAI(task,materials,question=''){if(!materials.length&&task!=='verify')return toast('请选择资料');if(!S.cfg.url||!S.cfg.key||!S.cfg.model)return dialog('模型接口',`<div class="v7-actions">${btn('go-settings','前往设置','','v7-btn primary')}</div>`);dialog('处理中','<p class="v8-muted">正在生成…</p>');try{const result=await requestAI(S.cfg,task,materials,question);S.ai={result,materials,task};const labels={supported:'公开来源支持',contradicted:'与公开来源矛盾',unverifiable:'未找到足够依据'};dialog(result.title,`<span class="v8-eyebrow">模型生成${result.verdict?' · '+labels[result.verdict]:''}</span>${result.points.map(p=>`<p>${h(p.text)}</p><div class="v7-actions">${p.sourceIds.map(id=>{const s=materials.find(x=>x.id===id);return ext(s.url,(s.date||'来源')+(s.locator?' · '+s.locator:''));}).join('')}</div>`).join('')}<div class="v7-actions">${btn('collect-ai','收藏结果')}${btn('copy-ai','复制')}</div>`);}catch(e){dialog('未能生成结果',`<p>${h(e.name==='AbortError'?'请求超时':e.message)}</p>`);}}
async function onClick(e){if(e.target.closest('#v7-nav a[href="#holdings"],.v7-brand')){S.focus='portfolio';S.detail='portfolio';if(S.view==='holdings')render();}
 const el=e.target.closest('[data-act]');if(!el)return;const act=el.dataset.act,id=el.dataset.id;try{
 if(act==='close')return close();if(act==='edit-holdings')return editHoldings();
 if(act==='remove-holding'){syncEditor();editingRows.splice(Number(id),1);return showHoldingEditor();}
 if(act==='add-fund'){const row=(L1||[]).find(x=>x[0]===id);if(!row)return;$('#v7-q').value='';$('#v7-results').innerHTML='';if($('#holding-form')){syncEditor();if(!editingRows.some(r=>r.code===id))editingRows.push({code:id,name:row[1],type:row[2],amount:''});return showHoldingEditor();}addingFund=row;return dialog(row[1],`<form id="quick-add-form"><label class="v7-field"><span>当前持有金额（元）</span><input name="amount" type="number" min="0.01" step="0.01" value="${h(S.account.items.find(x=>x.code===id)?.amount??'')}" required autofocus></label><button class="v7-btn primary">保存持仓</button></form>`);}
 if(act==='inspect')return showDetail(id);if(act==='all-related')return paintInspector(!$('#v8-inspector').dataset.all);
 if(act==='graph-home'){S.focus='portfolio';showDetail('portfolio');graph.update(model(),S.focus);$('#graph-focus-label').textContent='';return;}if(act==='graph-minus')return graph?.zoom(1/1.15);if(act==='graph-plus')return graph?.zoom(1.15);if(act==='graph-fit')return graph?.fit();
 if(act==='analysis-tab'){S.analysis=id;return render();}
 if(act==='timeline-mode'){S.timelineMode=id;S.timelineId='';S.timelineSearch='';S.selected.clear();return render();}if(act==='older'){S.older=!S.older;if(S.older&&!D.archivesLoaded){const index=await loadPublicData('archive/index.json',await get('data/archive/index.json',{months:[]}));const groups=await Promise.all(index.months.filter(x=>/^\d{4}-\d{2}$/.test(x)).map(async month=>loadPublicData('archive/'+month+'.json',await get('data/archive/'+month+'.json',{events:[]}))));D.archivedEvents=groups.flatMap(x=>x.events);D.events=[...new Map([...D.events,...D.archivedEvents].map(e=>[e.id,e])).values()];D.archivesLoaded=true;}return render();}
 if(act==='go-timeline'){S.timelineMode=id.startsWith('fund')?'fund':'company';S.timelineId=id;return location.hash='news';}
 if(act==='go-source'){S.sourceId=id;return location.hash='sources';}if(act==='source-detail')return showSource(id);
 if(act==='discussion-mode'){S.discussionId=id==='fund'?'':'stock';return render();}
 if(act==='collect-event'){const ev=D.events.find(x=>x.id===id);return library.collect({title:ev.title,url:ev.url,excerpt:ev.summary||'',referenceId:'event:'+id});}
 if(act==='collect-source'){const s=D.reference.sources.find(x=>x.id===id);return library.collect({title:s.title,url:s.url,excerpt:sourceHighlights(s).map(x=>x.text).join('\n\n'),referenceId:s.id});}
 if(act==='source-summary'){const s=D.reference.sources.find(x=>x.id===id);return runAI('summary',[{id:s.id,text:sourceHighlights(s).map(x=>x.text).join('\n'),url:s.url,date:s.publishedAt,locator:(s.locator||'').replace(/[（(]零基页号[^）)]*[）)]/g,'')}]);}
 if(act==='source-qa')return dialog('资料问答','<form id="qa-form"><label class="v7-field"><textarea name="question" placeholder="输入问题" rows="3" required></textarea></label><button class="v7-btn primary">提问</button></form>');
 if(act==='ai-summary')return runAI('summary',D.events.filter(x=>S.selected.has(x.id)).map(x=>({id:x.id,text:[x.date,x.title,x.summary].join(' '),url:x.url,date:x.date})));
 if(act==='collect-forum'){const r=D.forum.records.find(x=>x.id===id);return library.collect({title:r.title,url:r.url,excerpt:r.claim||'',referenceId:'forum:'+r.id});}
 if(act==='forum-verify'){const r=D.forum.records.find(x=>x.id===id);return runAI('verify',evidenceMaterials(S.discussionId),r.claim||r.title);}
 if(act==='collect-ai'){const ids=new Set(S.ai.result.points.flatMap(p=>p.sourceIds));const refs=S.ai.materials.filter(s=>ids.has(s.id));return library.collect({title:S.ai.result.title,excerpt:S.ai.result.points.map(p=>p.text).join('\n'),url:refs[0]?.url||'',note:'模型生成'+refs.map(s=>'\n'+(s.date||'')+' '+s.url).join(''),referenceId:'ai:'+crypto.randomUUID()});}
 if(act==='copy-ai')return navigator.clipboard.writeText(S.ai.result.points.map(p=>p.text).join('\n')).then(()=>toast('已复制'));
 if(act==='go-settings'){close();return location.hash='settings';}
 if(act==='export-account'){const blob=new Blob([JSON.stringify({format:'zhijian-holdings',...S.account},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='持仓.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;}
 if(act==='import-account')return $('#account-file').click();
 }catch(err){toast(err.message);}}
function syncEditor(){for(const el of document.querySelectorAll('[data-amount-index]'))editingRows[Number(el.dataset.amountIndex)].amount=el.value;}
function saveAccount(rows){const value={...normalizeAmounts(rows),savedAt:new Date().toISOString()};if(put('zhijian-holdings-v08',value)){S.account=value;S.focus='portfolio';S.detail='portfolio';S.timelineId='';close();render();toast('持仓已保存');}}
async function onSubmit(e){const form=e.target,id=form.id;if(!['holding-form','quick-add-form','scenario-form','bounds-form','settings-form','verify-form','qa-form'].includes(id))return;e.preventDefault();const data=Object.fromEntries(new FormData(form));try{
 if(id==='holding-form'){syncEditor();return saveAccount(editingRows);}
 if(id==='quick-add-form'){const items=structuredClone(S.account.items),existing=items.find(x=>x.code===addingFund[0]);if(existing)existing.amount=data.amount;else items.push({code:addingFund[0],name:addingFund[1],type:addingFund[2],amount:data.amount});return saveAccount(items);}
 if(id==='settings-form'){if(put('zhijian-v07-cfg',data)){S.cfg=data;toast('已保存');}return;}
 if(id==='bounds-form'){const value={};for(const [k,v]of Object.entries(data)){value[k]=v===''?null:Number(v);if(value[k]!==null&&(!Number.isFinite(value[k])||value[k]<0||k==='loss'&&value[k]===0||k!=='loss'&&value[k]>100))throw Error('上限数值无效');}if(put('zhijian-boundaries-v08',value)){S.bounds=value;render();toast('已保存');}return;}
 if(id==='scenario-form'){const m=model(),shock=Number(data.shock);if(!Number.isFinite(shock)||shock< -100||shock>100)throw Error('涨跌幅须为−100%至100%');const share=data.scope==='all'?100:m.funds.find(f=>f.id===data.scope)?.share??m.companies.find(c=>c.id===data.scope)?.share;if(!Number.isFinite(share))throw Error('请选择对象');const amount=m.total*share/100*shock/100;$('#scenario-result').innerHTML=`<div class="v8-metrics">${metric('组合变化',pct(share*shock/100))}${metric('金额变化',cash(amount))}</div>${S.bounds.loss!==null?`<small>${Math.max(0,-amount)>S.bounds.loss?'超过损失关注金额':'未超过损失关注金额'}</small>`:''}`;return;}
 if(id==='verify-form')return runAI('verify',evidenceMaterials(S.discussionId),String(data.claim).replace(/@\S+/g,'').trim());
 if(id==='qa-form')return runAI('qa',evidenceMaterials(),data.question);
 }catch(err){toast(err.message);}}
async function onChange(e){const el=e.target;if(el.dataset.eventPick){el.checked?S.selected.add(el.dataset.eventPick):S.selected.delete(el.dataset.eventPick);const b=document.querySelector('[data-act="ai-summary"]');if(b)b.disabled=!S.selected.size;return;}
 if(el.matches('[data-timeline-object]')){S.timelineId=el.value;S.selected.clear();return render();}if(el.matches('[data-discussion-object]')){S.discussionId=el.value;return render();}
 if(el.id==='source-object'){S.sourceId=el.value;return render();}
 if(el.id==='account-file'&&el.files[0])try{const data=JSON.parse(await el.files[0].text());if(data.format!=='zhijian-holdings')throw Error('持仓文件格式无效');saveAccount(data.items);}catch(err){toast(err.message);}}
function onInput(e){const el=e.target;if(el.id==='holding-search')search(el.value,$('#holding-results')).catch(err=>toast(err.message));if(el.id==='v7-q')search(el.value,$('#v7-results')).catch(err=>toast(err.message));
 if(el.dataset.amountIndex!==undefined){syncEditor();$('#editor-total').textContent=cash(editingRows.reduce((s,r)=>s+(Number(r.amount)||0),0));}
 if(el.matches('[data-timeline-search]')){S.timelineSearch=el.value;searchTimeline(el).catch(err=>toast(err.message));}
 if(el.matches('[data-discussion-search]')){S.discussionSearch=el.value;const mode=S.discussionId.startsWith('stock')?'company':'fund';document.querySelector('[data-discussion-object]').innerHTML='<option value="">选择对象</option>'+opts(objectList(mode).filter(x=>x.id===S.discussionId||[x.name,x.code].join(' ').includes(el.value)).map(x=>[x.id,x.name+' · '+x.code]),S.discussionId);}
 if(el.id==='source-query'){S.sourceQuery=el.value;clearTimeout(onInput.t);onInput.t=setTimeout(()=>{const pos=el.selectionStart;render();$('#source-query').focus();$('#source-query').setSelectionRange(pos,pos);},250);}
 if(el.closest('#scenario-form')&&$('#scenario-result'))$('#scenario-result').innerHTML='';}
boot().catch(err=>{$('#v7-view').innerHTML='<div class="v7-empty">页面未能加载，请刷新重试。</div>';console.error(err);});
